"""
Module for reading user storage sync progress.

When a user pod launches on qBraid infrastructure (cloud=True), files are synced
from bucket storage to the pod. Progress is tracked in ~/.qbraid_sync_progress.json.

"""

import json
import logging
from enum import Enum
from pathlib import Path
from typing import Optional

from pydantic import BaseModel, ConfigDict

logger = logging.getLogger(__name__)

DEFAULT_SYNC_PROGRESS_PATH = Path.home() / ".qbraid_sync_progress.json"


class SyncStatus(str, Enum):
    """Overall sync status values."""

    IN_PROGRESS = "in_progress"
    COMPLETE = "complete"
    PARTIAL = "partial"
    ERROR = "error"


class SyncState(str, Enum):
    """Individual sync operation state values."""

    PENDING = "pending"
    DOWNLOADING = "downloading"
    EXTRACTING = "extracting"
    COMPLETED = "completed"
    SKIPPED = "skipped"
    ERROR = "error"


class SyncOperation(BaseModel):
    """Model for individual sync operation (env_sync or file_sync)."""

    model_config = ConfigDict(extra="ignore")

    state: SyncState = SyncState.PENDING
    progress: int = 0
    message: str = ""
    tarball_bytes: int = 0
    error: Optional[str] = None


class SyncProgress(BaseModel):
    """Model for the sync progress file schema."""

    model_config = ConfigDict(extra="ignore")

    version: int = 2
    status: SyncStatus = SyncStatus.IN_PROGRESS
    disk_usage_mb: int = 0
    started_at: int = 0
    updated_at: int = 0
    env_sync: SyncOperation = SyncOperation()
    file_sync: SyncOperation = SyncOperation()

    @property
    def overall_progress(self) -> int:
        """Calculate overall progress percentage (0-100)."""
        return (self.env_sync.progress + self.file_sync.progress) // 2


def get_sync_progress(file_path: Optional[Path] = None) -> SyncProgress:
    """Read and parse sync progress from JSON file.

    Args:
        file_path: Path to sync progress file. Defaults to ~/.qbraid_sync_progress.json

    Returns:
        SyncProgress object with status, progress percentages, timestamps, etc.

    Raises:
        FileNotFoundError: If sync progress file does not exist.
        json.JSONDecodeError: If file contains invalid JSON.
        ValueError: If JSON doesn't match expected schema.
    """
    progress_path = file_path or DEFAULT_SYNC_PROGRESS_PATH

    if not progress_path.exists():
        raise FileNotFoundError(f"Sync progress file not found: {progress_path}")

    with progress_path.open("r", encoding="utf-8") as f:
        data = json.load(f)
        return SyncProgress(**data)


def is_sync_in_progress() -> bool:
    """Check if cloud file sync is currently in progress.

    This should be checked before performing registry sync operations to avoid
    corrupting the registry while environment files are still being extracted.

    Checks ~/.qbraid_sync_progress.json for status IN_PROGRESS.

    Returns:
        bool: True if sync is in progress and registry operations should be skipped.
    """
    try:
        progress = get_sync_progress()
        if progress.status == SyncStatus.IN_PROGRESS:
            logger.debug(
                "Sync in progress: status=%s, progress=%d%%",
                progress.status.value,
                progress.overall_progress,
            )
            return True
    except FileNotFoundError:
        # No sync progress file means no cloud sync in progress
        pass
    except (json.JSONDecodeError, ValueError) as err:
        # If we can't read the file, log warning but assume not syncing
        logger.warning("Failed to read sync progress file: %s", err)

    return False
